import { describe, expect, it } from "vitest";
import handler from "../api/mcp.js";

const URL = "https://modelparams.dev/mcp";

async function rpc(body: unknown, init: RequestInit = {}): Promise<Response> {
  return await handler.fetch(
    new Request(URL, {
      method: "POST",
      headers: { "Content-Type": "application/json", Accept: "application/json" },
      body: typeof body === "string" ? body : JSON.stringify(body),
      ...init,
    }),
  );
}

interface RpcReply {
  jsonrpc: string;
  id?: number | string | null;
  result?: Record<string, unknown>;
  error?: { code: number; message: string };
}

async function call(name: string, args: Record<string, unknown>): Promise<Record<string, unknown>> {
  const res = await rpc({
    jsonrpc: "2.0",
    id: 2,
    method: "tools/call",
    params: { name, arguments: args },
  });
  const body = (await res.json()) as RpcReply;
  const content = (body.result as { content: { type: string; text: string }[] }).content;
  return JSON.parse(content[0]!.text) as Record<string, unknown>;
}

describe("POST /mcp", () => {
  it("completes the initialize handshake", async () => {
    const res = await rpc({
      jsonrpc: "2.0",
      id: 1,
      method: "initialize",
      params: {
        protocolVersion: "2025-06-18",
        capabilities: {},
        clientInfo: { name: "test", version: "0" },
      },
    });
    expect(res.status).toBe(200);
    const body = (await res.json()) as RpcReply;
    const result = body.result as {
      serverInfo: { name: string };
      capabilities: Record<string, unknown>;
    };
    expect(result.serverInfo.name).toBe("modelparams");
    expect(result.capabilities.tools).toBeDefined();
  });

  it("lists the four catalog tools", async () => {
    const res = await rpc({ jsonrpc: "2.0", id: 2, method: "tools/list" });
    const body = (await res.json()) as RpcReply;
    const names = (body.result as { tools: { name: string }[] }).tools.map((t) => t.name).sort();
    expect(names).toEqual([
      "get_model_params",
      "list_models",
      "list_provider_models",
      "validate_model_params",
    ]);
  });

  it("answers a real catalog question", async () => {
    const result = await call("get_model_params", { model: "openai/gpt-4" });
    expect(result.model).toBe("openai/gpt-4");
    expect(result.parameterCount as number).toBeGreaterThan(0);
  });

  it("validates params, which is the tool agents should call first", async () => {
    const result = await call("validate_model_params", {
      model: "openai/gpt-4",
      params: { temperature: 0.5, nonsense_param: 1 },
    });
    expect(result.valid).toBe(false);
    expect(JSON.stringify(result.issues)).toContain("nonsense_param");
    expect(result.safeParams).toEqual({ temperature: 0.5 });
  });

  it("serves the catalog the site was built from, not a pinned npm version", async () => {
    // The stdio package answers from `modelparams@<exact pin>`; this endpoint
    // answers from the build. A model merged today must be present here.
    const result = await call("list_models", { provider: "bedrock" });
    expect((result.models as string[]).length).toBeGreaterThan(0);
  });

  it("accepts a notification with no body", async () => {
    const res = await rpc({ jsonrpc: "2.0", method: "notifications/initialized" });
    expect(res.status).toBe(202);
    expect(await res.text()).toBe("");
  });

  it("rejects a JSON-RPC batch instead of answering only its first message", async () => {
    const res = await rpc([{ jsonrpc: "2.0", id: 1, method: "tools/list" }]);
    expect(res.status).toBe(400);
    const body = (await res.json()) as RpcReply;
    expect(body.error?.message).toContain("batch");
  });

  it("rejects a malformed body", async () => {
    const res = await rpc("{not json");
    expect(res.status).toBe(400);
    expect(((await res.json()) as RpcReply).error?.code).toBe(-32700);
  });

  it("answers a browser GET with usage, and an SSE GET with 405", async () => {
    const usage = await handler.fetch(new Request(URL));
    expect(usage.status).toBe(200);
    expect(((await usage.json()) as { transport: string }).transport).toBe("streamable-http");

    const stream = await handler.fetch(
      new Request(URL, { headers: { Accept: "text/event-stream" } }),
    );
    expect(stream.status).toBe(405);
    expect(stream.headers.get("Allow")).toBe("POST");
  });

  it("never lets a shared cache hold a response", async () => {
    const res = await rpc({ jsonrpc: "2.0", id: 3, method: "tools/list" });
    expect(res.headers.get("Cache-Control")).toBe("no-store");
    expect(res.headers.get("Access-Control-Allow-Origin")).toBe("*");
  });
});

import { afterEach, describe, expect, it, vi } from "vitest";
import {
  classifyClient,
  classifyEndpoint,
  eventProperties,
  ingestUrl,
  trackApiUsage,
} from "../src/tracking/api-usage.js";

describe("classifyEndpoint", () => {
  it("recognises the fixed endpoints", () => {
    expect(classifyEndpoint("/api/v1/index.json").endpoint).toBe("index");
    expect(classifyEndpoint("/api/v1/models.json").endpoint).toBe("catalog");
    expect(classifyEndpoint("/api/v1/schema.json").endpoint).toBe("schema");
    expect(classifyEndpoint("/api/v1/validate").endpoint).toBe("validate");
    expect(classifyEndpoint("/api/v1/validate/").endpoint).toBe("validate");
    expect(classifyEndpoint("/llms.txt").endpoint).toBe("llms");
    expect(classifyEndpoint("/llms-full.txt").endpoint).toBe("llms");
  });

  it("recognises the MCP server on both its public and rewritten paths", () => {
    expect(classifyEndpoint("/mcp").endpoint).toBe("mcp");
    expect(classifyEndpoint("/api/mcp").endpoint).toBe("mcp");
  });

  it("extracts provider and model from model_by_id paths", () => {
    expect(classifyEndpoint("/api/v1/models/openai/gpt-4.1.json")).toEqual({
      endpoint: "model_by_id",
      authMode: "api_key",
      provider: "openai",
      model: "gpt-4.1",
    });
  });

  it("splits the -subscription suffix into auth_mode", () => {
    expect(classifyEndpoint("/api/v1/models/openai/gpt-4.1-subscription.json")).toEqual({
      endpoint: "model_by_id",
      authMode: "subscription",
      provider: "openai",
      model: "gpt-4.1",
    });
    expect(classifyEndpoint("/api/v1/params/gpt-5.5-subscription.json")).toEqual({
      endpoint: "params_by_model",
      authMode: "subscription",
      provider: null,
      model: "gpt-5.5",
    });
  });

  it("extracts the model from params_by_model paths", () => {
    expect(classifyEndpoint("/api/v1/params/gpt-5.5.json")).toEqual({
      endpoint: "params_by_model",
      authMode: "api_key",
      provider: null,
      model: "gpt-5.5",
    });
  });

  it("buckets anything else as other", () => {
    expect(classifyEndpoint("/api/v1/nope").endpoint).toBe("other");
    expect(classifyEndpoint("/api/v1/models/openai/too/deep.json").endpoint).toBe("other");
    expect(classifyEndpoint("/").endpoint).toBe("other");
  });
});

describe("classifyClient", () => {
  it.each([
    ["curl/8.6.0", "curl"],
    ["Wget/1.21", "wget"],
    ["python-requests/2.32.0", "python"],
    ["python-httpx/0.27.0", "python"],
    ["node-fetch/3.3.2", "node"],
    ["undici", "node"],
    ["axios/1.7.2", "node"],
    ["Go-http-client/2.0", "go"],
    ["Mozilla/5.0 (compatible; GPTBot/1.2; +https://openai.com/gptbot)", "bot"],
    ["Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 Chrome/126.0 Safari/537.36", "browser"],
    ["SomethingElse/1.0", "other"],
  ])("classifies %s as %s", (userAgent, expected) => {
    expect(classifyClient(userAgent)).toBe(expected);
  });

  it("treats a missing user agent as unknown", () => {
    expect(classifyClient(null)).toBe("unknown");
    expect(classifyClient("")).toBe("unknown");
  });
});

describe("eventProperties", () => {
  it("describes a model params request", () => {
    const request = new Request("https://modelparams.dev/api/v1/params/gpt-5.5.json", {
      headers: { "user-agent": "python-requests/2.32.0" },
    });
    expect(eventProperties(request)).toEqual({
      path: "/api/v1/params/gpt-5.5.json",
      method: "GET",
      endpoint: "params_by_model",
      client: "python",
      auth_mode: "api_key",
      model: "gpt-5.5",
    });
  });

  it("omits absent values instead of sending null", () => {
    const request = new Request("https://modelparams.dev/api/v1/models.json");
    expect(eventProperties(request)).toEqual({
      path: "/api/v1/models.json",
      method: "GET",
      endpoint: "catalog",
      client: "unknown",
    });
  });
});

