  });
});

describe("trackApiUsage", () => {
  afterEach(() => {
    vi.unstubAllGlobals();
  });

  const env = { VERCEL_URL: "modelparams-abc123.vercel.app" };
  const request = (method = "GET") =>
    new Request("https://modelparams.dev/api/v1/models.json", {
      method,
      headers: {
        "user-agent": "curl/8.6.0",
        "x-forwarded-for": "203.0.113.7",
      },
    });

  it("is a no-op off Vercel and for CORS preflights", () => {
    const fetchMock = vi.fn();
    vi.stubGlobal("fetch", fetchMock);
    expect(trackApiUsage(request(), {})).toBe(null);
    expect(trackApiUsage(request("OPTIONS"), env)).toBe(null);
    expect(fetchMock).not.toHaveBeenCalled();
  });

  it("posts the @vercel/analytics wire format to the ingest route", async () => {
    const fetchMock = vi.fn().mockResolvedValue(new Response("ok"));
    vi.stubGlobal("fetch", fetchMock);

    await trackApiUsage(request(), env);

    expect(fetchMock).toHaveBeenCalledTimes(1);
    const [url, init] = fetchMock.mock.calls[0] as [
      string,
      { method: string; headers: Record<string, string>; body: string },
    ];
    expect(url).toBe("https://modelparams-abc123.vercel.app/_vercel/insights/event");
    expect(init.method).toBe("POST");
    expect(init.headers).toMatchObject({
      "content-type": "application/json",
      "x-va-server": "1",
      "user-agent": "curl/8.6.0",
      "x-vercel-ip": "203.0.113.7",
    });
    expect(init.headers).not.toHaveProperty("cookie");

    const body = JSON.parse(init.body) as {
      en: string;
      o: string;
      sdkn: string;
      ed: Record<string, string>;
    };
    expect(body.en).toBe("api_request");
    expect(body.o).toBe("https://modelparams.dev/api/v1/models.json");
    expect(body.sdkn).toBe("@vercel/analytics/server");
    expect(body.ed).toMatchObject({ endpoint: "catalog", client: "curl" });
  });

  it("sends the protection bypass secret when configured", async () => {
    const fetchMock = vi.fn().mockResolvedValue(new Response("ok"));
    vi.stubGlobal("fetch", fetchMock);

    await trackApiUsage(request(), { ...env, VERCEL_AUTOMATION_BYPASS_SECRET: "shh" });

    const [, init] = fetchMock.mock.calls[0] as [string, { headers: Record<string, string> }];
    expect(init.headers["x-vercel-protection-bypass"]).toBe("shh");
  });

  it("swallows network failures", async () => {
    vi.stubGlobal("fetch", vi.fn().mockRejectedValue(new Error("offline")));
    await expect(trackApiUsage(request(), env)).resolves.toBe(undefined);
  });
});

import { describe, expect, it } from "vitest";
import { modelId, searchCatalog } from "../src/client/webmcp.js";

type AuthType = "api_key" | "subscription";

function model(
  provider: string,
  name: string,
  authType: AuthType,
  paths: string[],
  apiSurface = provider === "anthropic" ? "anthropic-messages" : "openai-chat-completions",
) {
  return {
    provider,
    model: name,
    authType,
    apiSurface,
    params: paths.map((path) => ({
      path,
      type: "number",
      group: "sampling",
      description: "",
    })),
  };
}

function catalog(...models: ReturnType<typeof model>[]) {
  return { count: models.length, models };
}

const CATALOG = catalog(
  model("anthropic", "claude-opus-4-7", "api_key", ["temperature", "thinking.type", "max_tokens"]),
  model("anthropic", "claude-opus-4-7", "subscription", ["temperature", "thinking.type"]),
  model("openai", "gpt-4o", "api_key", ["temperature", "top_p"]),
  model("deepseek", "deepseek-chat", "api_key", ["temperature"]),
);

describe("modelId", () => {
  it("leaves api_key models bare", () => {
    expect(modelId(model("openai", "gpt-4o", "api_key", []))).toBe("openai/gpt-4o");
  });

  it("suffixes subscription models", () => {
    expect(modelId(model("anthropic", "claude-opus-4-7", "subscription", []))).toBe(
      "anthropic/claude-opus-4-7-subscription",
    );
  });
});

describe("searchCatalog", () => {
  it("returns every model when no filters are given", () => {
    const result = searchCatalog(CATALOG, {});
    expect(result.total).toBe(4);
    expect(result.returned).toBe(4);
    expect(result.truncated).toBe(false);
  });

  it("matches free-text query case-insensitively on name, provider, or id", () => {
    expect(searchCatalog(CATALOG, { query: "opus" }).total).toBe(2);
    expect(searchCatalog(CATALOG, { query: "OPUS" }).total).toBe(2);
    expect(searchCatalog(CATALOG, { query: "openai" }).total).toBe(1);
    expect(searchCatalog(CATALOG, { query: "nonsense" }).total).toBe(0);
  });

  it("filters by provider slug", () => {
    const result = searchCatalog(CATALOG, { provider: "anthropic" });
    expect(result.total).toBe(2);
    expect(result.models.every((m) => m.provider === "anthropic")).toBe(true);
  });

  it("requires the model to expose every requested capability", () => {
    expect(searchCatalog(CATALOG, { capability: "thinking.type" }).total).toBe(2);
    expect(searchCatalog(CATALOG, { capability: ["thinking.type", "max_tokens"] }).total).toBe(1);
    expect(searchCatalog(CATALOG, { capability: "does.not.exist" }).total).toBe(0);
  });

  it("filters by auth type and treats `all` as no filter", () => {
    expect(searchCatalog(CATALOG, { auth: "subscription" }).total).toBe(1);
    expect(searchCatalog(CATALOG, { auth: "api_key" }).total).toBe(3);
    expect(searchCatalog(CATALOG, { auth: "all" }).total).toBe(4);
  });

  it("filters by API surface", () => {
    expect(searchCatalog(CATALOG, { apiSurface: "anthropic-messages" }).total).toBe(2);
    expect(searchCatalog(CATALOG, { apiSurface: "openai-chat-completions" }).total).toBe(2);
  });

  it("combines filters (AND semantics)", () => {
    const result = searchCatalog(CATALOG, { provider: "anthropic", auth: "api_key" });
    expect(result.total).toBe(1);
    expect(result.models[0]?.id).toBe("anthropic/claude-opus-4-7");
  });

  it("caps results at the limit and flags truncation", () => {
    const result = searchCatalog(CATALOG, { limit: 1 });
    expect(result.total).toBe(4);
    expect(result.returned).toBe(1);
    expect(result.truncated).toBe(true);
    expect(result.models).toHaveLength(1);
  });

  it("clamps a non-positive limit to at least one result", () => {
    expect(searchCatalog(CATALOG, { limit: 0 }).models).toHaveLength(1);
  });

  it("returns id, auth, and parameter paths for each match", () => {
    const sub = searchCatalog(CATALOG, { auth: "subscription" }).models[0];
    expect(sub).toMatchObject({
      id: "anthropic/claude-opus-4-7-subscription",
      provider: "anthropic",
      authType: "subscription",
      apiSurface: "anthropic-messages",
      parameterCount: 2,
    });
    expect(sub?.parameters).toEqual(["temperature", "thinking.type"]);
  });
});

import { describe, it, expect } from "vitest";
import { buildLlmsFullTxt, buildLlmsTxt, usageGuideMarkdown } from "../src/data/llms.js";
import type { Model } from "../src/schema/model.js";

const SITE = "https://modelparams.dev";

function makeModel(overrides: Partial<Model> = {}): Model {
  return {
    provider: "anthropic",
    authType: "api_key",
    apiSurface: "anthropic-messages",
    model: "claude-opus-4-7",
    params: [
      {
        path: "max_tokens",
        type: "integer",
        label: "Max tokens",
        description: "Maximum output tokens.",
        default: 4096,
        range: { min: 1 },
        group: "generation_length",
      },
      {
        path: "thinking.display",
        type: "enum",
        label: "Thinking display",
        description: "Whether thinking is summarized.",
        default: "omitted",
        values: ["summarized", "omitted"],
        group: "reasoning",
        applicability: { only: { "thinking.type": ["adaptive"] } },
      },
    ],
    ...overrides,
  } as Model;
}

describe("usageGuideMarkdown", () => {
  it("renders the guide as Markdown with the catalog endpoints", () => {
    const md = usageGuideMarkdown(SITE);
    expect(md.startsWith("# How to use modelparams.dev")).toBe(true);
    expect(md).toContain(`curl ${SITE}/api/v1/models.json`);
    expect(md).toContain(`curl ${SITE}/api/v1/models/openai/gpt-5.5.json`);
    expect(md).toContain(`curl ${SITE}/api/v1/models/openai/gpt-5.5-subscription.json`);
    expect(md).toContain(`curl ${SITE}/api/v1/schema.json`);
    expect(md).toContain(`${SITE}/llms-full.txt`);
    expect(md).toContain("WebMCP");
  });

  it("threads the provided site url through every reference", () => {
    const md = usageGuideMarkdown("http://localhost:3000");
    expect(md).toContain("curl http://localhost:3000/api/v1/models.json");
    expect(md).toContain("curl http://localhost:3000/api/v1/models/openai/gpt-5.5.json");
    expect(md).not.toContain("https://modelparams.dev");
  });
});

describe("buildLlmsTxt", () => {
  it("follows the llms.txt shape: H1, summary, sections, model links", () => {
    const txt = buildLlmsTxt(SITE, [makeModel(), makeModel({ authType: "subscription" })]);
    expect(txt.startsWith("# modelparams.dev")).toBe(true);
    expect(txt).toContain("\n> An open, community-maintained catalog");
    expect(txt).toContain("## API");
    expect(txt).toContain(`${SITE}/api/v1/models/openai/gpt-5.5.json`);
    expect(txt).toContain("## Models");
    expect(txt).toContain("## Optional");
    expect(txt).toContain(
      `- [anthropic/claude-opus-4-7](${SITE}/api/v1/models/anthropic/claude-opus-4-7.json):`,
    );
    expect(txt).toContain(
      `- [anthropic/claude-opus-4-7-subscription](${SITE}/api/v1/models/anthropic/claude-opus-4-7-subscription.json):`,
    );
    expect(txt).toContain("2 parameters.");
  });

  it("singularizes a one-parameter model", () => {
    const txt = buildLlmsTxt(SITE, [makeModel({ params: [makeModel().params[0]!] })]);
    expect(txt).toContain("1 parameter.");
  });
});

describe("buildLlmsFullTxt", () => {
  it("embeds the usage guide and dumps each parameter with constraints", () => {
    const full = buildLlmsFullTxt(SITE, [makeModel()]);
    expect(full).toContain("# How to use modelparams.dev");
    expect(full).toContain("# Full catalog");
    expect(full).toContain("## Anthropic");
    expect(full).toContain("### anthropic/claude-opus-4-7");
    expect(full).toContain(
      "- `max_tokens` (integer, Length) — Maximum output tokens. [default: 4096] [range: min 1]",
    );
    expect(full).toContain(
      '- `thinking.display` (enum, Reasoning) — Whether thinking is summarized. [default: "omitted"] [values: "summarized", "omitted"] [only when thinking.type = "adaptive"]',
    );
  });

  it("notes models that have no parameters yet", () => {
    const full = buildLlmsFullTxt(SITE, [makeModel({ params: [] })]);
    expect(full).toContain("_No parameters documented yet._");
  });
});

import http from "node:http";
import type { AddressInfo } from "node:net";
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StreamableHTTPClientTransport } from "@modelcontextprotocol/sdk/client/streamableHttp.js";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import handler from "../api/mcp.js";

// The unit tests above drive the handler with hand-written JSON-RPC. This one
// puts the real SDK client in front of it over real HTTP, which is what Claude
// Code and Codex do — protocol details we get wrong show up here, not there.
let server: http.Server;
let client: Client;

beforeAll(async () => {
  server = http.createServer((req, res) => {
    const chunks: Buffer[] = [];
    req.on("data", (chunk: Buffer) => chunks.push(chunk));
    req.on("end", () => {
      void (async () => {
        const body = Buffer.concat(chunks);
        const response = await handler.fetch(
          new Request(`http://localhost${req.url ?? "/"}`, {
            method: req.method,
            headers: req.headers as Record<string, string>,
            body: req.method === "GET" || req.method === "HEAD" ? undefined : body,
          }),
        );
        res.writeHead(response.status, Object.fromEntries(response.headers));
        res.end(Buffer.from(await response.arrayBuffer()));
      })();
    });
  });
  await new Promise<void>((resolve) => server.listen(0, resolve));
  const { port } = server.address() as AddressInfo;

  client = new Client({ name: "protocol-test", version: "1" });
  await client.connect(new StreamableHTTPClientTransport(new URL(`http://localhost:${port}/mcp`)));
});

afterAll(async () => {
  await client.close();
  server.close();
});

describe("the MCP endpoint over real HTTP", () => {
  it("completes the handshake a standard client performs", () => {
    expect(client.getServerVersion()?.name).toBe("modelparams");
  });

  it("advertises the four tools", async () => {
    const { tools } = await client.listTools();
    expect(tools.map((tool) => tool.name).sort()).toEqual([
      "get_model_params",
      "list_models",
      "list_provider_models",
      "validate_model_params",
    ]);
  });

  it("answers a tool call", async () => {
    const result = await client.callTool({
      name: "validate_model_params",
      arguments: { model: "anthropic/claude-opus-5", params: { temperature: 0.7 } },
    });
    const payload = JSON.parse((result.content as { text: string }[])[0]!.text) as {
      model: string;
      issues: unknown[];
    };
    expect(payload.model).toBe("anthropic/claude-opus-5");
    expect(Array.isArray(payload.issues)).toBe(true);
  });
});

